class Solution {
    public int minimumSplits(int[] nums) {
        int parts = 1, g = 0;
        for (int x : nums) {
            int ng = gcd(g, x);
            if (ng == 1) {
                parts++;
                g = x;
            } else {
                g = ng;
            }
        }
        return parts;
    }

    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}
